std::string Bytes(const fs::path&p){std::ifstream f(p,std::ios::binary);Need(bool(f),"read evidence");return {std::istreambuf_iterator<char>(f),{}};}
void Save(const fs::path&p,const std::string&b){std::ofstream f(p,std::ios::binary);f<<b;Need(bool(f),"write fixture");}
void Preset(Window&v,int index){auto c=GetDlgItem(v.h,IDC_QUALITY);SendMessageW(c,CB_SETCURSEL,index,0);SendMessageW(v.h,WM_COMMAND,MAKEWPARAM(IDC_QUALITY,CBN_SELCHANGE),LPARAM(c));}
void Press(Window&v,int id){SendMessageW(v.h,WM_COMMAND,MAKEWPARAM(id,BN_CLICKED),0);}
